void _reproject_slice_pp_c(int startx, int endx, int starty, int endy, int nx_out, int ny_out,
    double *xp_inout, double *yp_inout, double *array, double *array_new, double *weights,
    int col_in, int col_array, int col_new)
{
    int i, j, ii, jj, xmin, xmax, ymin, ymax;
    double ipoly_x[4], ipoly_y[4], minmax_x[4], minmax_y[4];
    double overlap;

    // Main loop.
    for (i = startx; i < endx; ++i) {
        for (j = starty; j < endy; ++j) {
            // For every input pixel we find the position in the output image in
            // pixel coordinates, then use the full range of overlapping output
            // pixels and compute the exact overlap in pixel space.

            minmax_x[0] = *GETPTR2(xp_inout,col_in,j,i);
            minmax_x[1] = *GETPTR2(xp_inout,col_in,j,i + 1);
            minmax_x[2] = *GETPTR2(xp_inout,col_in,j + 1,i + 1);
            minmax_x[3] = *GETPTR2(xp_inout,col_in,j + 1,i);

            minmax_y[0] = *GETPTR2(yp_inout,col_in,j,i);
            minmax_y[1] = *GETPTR2(yp_inout,col_in,j,i + 1);
            minmax_y[2] = *GETPTR2(yp_inout,col_in,j + 1,i + 1);
            minmax_y[3] = *GETPTR2(yp_inout,col_in,j + 1,i);

            xmin = (int)(min_4(minmax_x) + .5);
            xmax = (int)(max_4(minmax_x) + .5);
            ymin = (int)(min_4(minmax_y) + .5);
            ymax = (int)(max_4(minmax_y) + .5);

            // Fill in the input pixel polygon, in output pixel coordinates.
            // The corner ordering follows the one used by the spherical
            // implementation (counter-clockwise in pixel space).
            ipoly_x[0] = *GETPTR2(xp_inout,col_in,j+1,i);
            ipoly_y[0] = *GETPTR2(yp_inout,col_in,j+1,i);
            ipoly_x[1] = *GETPTR2(xp_inout,col_in,j+1,i+1);
            ipoly_y[1] = *GETPTR2(yp_inout,col_in,j+1,i+1);
            ipoly_x[2] = *GETPTR2(xp_inout,col_in,j,i+1);
            ipoly_y[2] = *GETPTR2(yp_inout,col_in,j,i+1);
            ipoly_x[3] = *GETPTR2(xp_inout,col_in,j,i);
            ipoly_y[3] = *GETPTR2(yp_inout,col_in,j,i);

            xmin = xmin > 0 ? xmin : 0;
            xmax = (nx_out-1) < xmax ? (nx_out-1) : xmax;
            ymin = ymin > 0 ? ymin : 0;
            ymax = (ny_out-1) < ymax ? (ny_out-1) : ymax;

            for (ii = xmin; ii < xmax + 1; ++ii) {
                for (jj = ymin; jj < ymax + 1; ++jj) {
                    // Compute the overlap in output pixel space. The output
                    // pixel has unit area in this space, so the returned
                    // overlap is the fractional coverage of the output pixel.
                    overlap = computeOverlapPP(ipoly_x, ipoly_y,
                                               ii - 0.5, ii + 0.5,
                                               jj - 0.5, jj + 0.5, 1.0);

                    // Write into array_new and weights.
                    *GETPTR2(array_new,col_new,jj,ii) += *GETPTR2(array,col_array,j,i) *
                                                                     overlap;

                    *GETPTR2(weights,col_new,jj,ii) += overlap;
                }
            }
        }
    }
}
